226		}
227		if _, _, err := good.SubmitResult("s1", "e2", Failed); err != nil {
228			t.Fatal(err)
229		}
230		if err := good.Save(path); err != nil {
231			t.Fatalf("前置正常保存失败：%v", err)
232		}
233		raw, err := os.ReadFile(path)
234		if err != nil {
235			t.Fatal(err)
236		}
