241			t.Fatal(err)
242		}
243		if _, _, err := bad.SubmitResult("s2", "e1", Failed); err != nil {
244			t.Fatal(err)
245		}
246		bad.Enrollment("s1", "e1").ResultSeq = 1
247		bad.Enrollment("s2", "e1").ResultSeq = 1
