249		assertSaveDupSeqError(t, saveErr, path, 1, "s1", "e1", "s2", "e1")
250	
251		got, err := os.ReadFile(path)
252		if err != nil {
253			t.Fatalf("原文件应继续可读：%v", err)
254		}
255		if string(got) != string(raw) {
256			t.Fatalf("拒绝保存后已有文件必须逐字节保持原样\nwant=%q\n got=%q", raw, got)
257		}
258		leftover, _ := filepath.Glob(filepath.Join(dir, ".credit-*.tmp"))
259		if len(leftover) != 0 {
